# Arabic editorial content (MSA, Gulf business-press style). Merged into data/*.json as *_ar fields.
import json
DEALS={
"12992a670a":("نابستر وهيوماين تتعاونان لنشر وكلاء ذكاء اصطناعي ناطقين بالعربية في المنطقة","أعلنت «نابستر» و«هيوماين» شراكة لنشر وكلاء ذكاء اصطناعي ناطقين بالعربية، تجمع نموذج «علّام» وتقنيات الكلام العربية لدى هيوماين مع بنية نابستر للوكلاء الصوتيين والمرئيين، لخدمة الجهات الحكومية والخاصة."),
"8488f32cd1":("أبوظبي تحدّث تطبيق «تم» ضمن مساعيها نحو حكومة قائمة على الذكاء الاصطناعي","تعتزم أبوظبي إطلاق نسخة محدّثة من تطبيق «تم» للخدمات الحكومية، في إطار هدفها التحول إلى حكومة قائمة بالكامل على الذكاء الاصطناعي بحلول 2027."),
"dbafc253c1":("دبي تطلق مسرّعة الذكاء الاصطناعي الوكيلي للخدمات الحكومية","أطلقت مؤسسة دبي للمستقبل مسرّعة لتوظيف الذكاء الاصطناعي الوكيلي في الخدمات الحكومية، بمشاركة 33 جهة حكومية وأكثر من 300 حالة استخدام."),
"40a230fd1c":("«اليمامة» تفوز بعقد البنية التحتية لحرم هيوماين للذكاء الاصطناعي في الرياض","فازت شركة اليمامة بعقد أعمال البنية التحتية التمكينية لحرم «السعد» التابع لهيوماين في الرياض بقدرة 6 غيغاواط، بعد طرح المناقصة في مايو الماضي."),
"7d3fac77e9":("«سينابس أناليتكس» تجمع 13 مليون دولار في جولة تمويل بقيادة «بارتك»","جمعت «سينابس أناليتكس»، ومقرها أبوظبي، 13 مليون دولار في جولة تمويل من الفئة (A) بقيادة «بارتك»، لتوسيع منصتها للذكاء الاصطناعي الوكيلي الموجهة للبنوك وشركات التقنية المالية."),
"7c5a825ec3":("«سرداب» تجمع 10 ملايين دولار بقيادة مشتركة من «علم» و«بيكو كابيتال»","جمعت منصة الخدمات اللوجستية السعودية «سرداب» 10 ملايين دولار (37.5 مليون ريال) في جولة تمويل من الفئة (A)، لدعم توسعها خليجياً وتطوير أدوات ذكاء اصطناعي تطابق الطلب مع السعة اللوجستية المتاحة."),
"2bff6ef94a":("هيوماين و«داتافولت» تطوّران مركز بيانات بنحو 100 ميغاواط في «أوكساجون»","تطوّر هيوماين نحو 100 ميغاواط ضمن المرحلة الأولى البالغة 360 ميغاواط من حرم داتافولت المخطط للذكاء الاصطناعي في أوكساجون بنيوم، ويُتوقع أن يكون جاهزاً في 2028."),
"fd5d360986":("هيوماين و«أمازون ويب سيرفيسز» توسّعان شراكتهما في البنية التحتية والنماذج","وسّعت هيوماين وAWS تعاونهما ليشمل إتاحة ما يصل إلى 50 ميغاواط من سعة «منطقة الذكاء الاصطناعي» بحلول 2028، وطرح منصة HUMAIN Fabric، وإتاحة نموذج «علّام» العربي عبر خدمة Amazon Bedrock."),
"37e2fb3d37":("«ستيلاريا» تغلق جولة تأسيسية بـ25 مليون درهم بتقييم 420 مليون درهم","أغلقت «ستيلاريا» الإماراتية، المتخصصة في الذكاء الاصطناعي الجيومكاني، جولة تمويل تأسيسية بقيمة 25 مليون درهم من مستثمرين أفراد، بتقييم بلغ 420 مليون درهم."),
"bded877a74":("«إم جي إكس» وشركاؤها يُتمّون الاستحواذ على «ألايند داتا سنترز»","أُنجزت صفقة استحواذ «إم جي إكس» و«شراكة البنية التحتية للذكاء الاصطناعي» و«جي آي بي» التابعة لبلاك روك على «ألايند داتا سنترز»، مع التزام إضافي بقيمة 5 مليارات دولار لتمويل توسعات الشركة."),
"be4e6e6fdf":("«كونتكست إيه آي» تغلق جولة تمويل بـ60 مليون دولار بقيادة «إيه آي 71»","أغلقت CNTXT AI الإماراتية، المتخصصة في البيانات والذكاء الاصطناعي السيادي، جولة تمويل من الفئة (A) بقيمة 60 مليون دولار بقيادة مشتركة من AI71 و«بلو فايف كابيتال»."),
"d01e088869":("«كيه كيه آر» وهيئة الاستثمار الكويتية تطلقان «هيليكس» بالتزامات تتجاوز 10 مليارات دولار","أطلقت «كيه كيه آر» شركة «هيليكس للبنية التحتية الرقمية» بالشراكة مع الهيئة العامة للاستثمار الكويتية و«إنفيديا» و«فيسترا»، بالتزامات رأسمالية تتجاوز 10 مليارات دولار لمراكز بيانات الذكاء الاصطناعي والطاقة والربط الشبكي."),
"f920b35fc5":("شركة «1001» تجمع 30 مليون دولار بقيادة «لوكس كابيتال» وبمشاركة «سنابل»","جمعت شركة 1001 للذكاء الاصطناعي 30 مليون دولار في جولة تمويل من الفئة (A) بقيادة «لوكس كابيتال» ومشاركة «سنابل للاستثمار»، لتوسيع حلولها للبنية التحتية الحيوية في دول الخليج."),
"e0c7e17c5b":("«جي42» و«سيريبراس» تنشران حاسوباً فائقاً سيادياً بقدرة 8 إكسافلوب في الهند","أعلنت «جي42» و«سيريبراس» نشر حاسوب فائق للذكاء الاصطناعي السيادي بقدرة 8 إكسافلوب في الهند، في توسع جديد لصادرات الإمارات من البنية التحتية للذكاء الاصطناعي."),
"b16ea60a36":("هيوماين تستثمر 3 مليارات دولار في جولة التمويل «E» لشركة «إكس إيه آي»","استثمرت هيوماين 3 مليارات دولار في جولة التمويل «E» لشركة xAI، وتحولت حصتها لاحقاً إلى أسهم في «سبيس إكس» عقب اندماج الشركتين."),
"dbc3e0d895":("العلماء: تكلفة حرم «ستارغيت الإمارات» تتجاوز 30 مليار دولار","قال عمر سلطان العلماء، وزير الدولة للذكاء الاصطناعي، إن تكلفة بناء حرم «ستارغيت الإمارات» بقدرة 5 غيغاواط ستتجاوز 30 مليار دولار، بزيادة تقارب 50% على التقديرات الأولية."),
"d37c428193":("تحالف «حسن علام» و«ستيرلينغ آند ويلسون» يفوز بعقد مركز بيانات لهيوماين","فاز تحالف «حسن علام للإنشاءات» و«ستيرلينغ آند ويلسون» بعقد قيمته 750 مليون ريال (نحو 200 مليون دولار) لتنفيذ المرحلة الأولى بقدرة 16.2 ميغاواط من مركز بيانات لهيوماين و«سنتر3» في الرياض."),
"5679f27d52":("«Signit» تجمع 15 مليون دولار في جولة تمويل بقيادة «رائد فنتشرز»","جمعت شركة Signit السعودية 15 مليون دولار في جولة تمويل من الفئة (A) بقيادة «رائد فنتشرز»، لتطوير منصتها لإدارة دورة حياة العقود بالذكاء الاصطناعي."),
"08847b0fce":("«سنتر3» وهيوماين توقعان مذكرة لمشروع مشترك لمراكز البيانات بقدرة 1 غيغاواط","وقّعت «سنتر3» التابعة لمجموعة stc مذكرة تفاهم مع هيوماين لتأسيس مشروع مشترك تملك هيوماين 51% منه، يستهدف 1 غيغاواط من سعة مراكز بيانات الذكاء الاصطناعي، بمرحلة أولى قدرها 250 ميغاواط."),
"5f7b322d5b":("«بروكفيلد» و«قاي» القطرية تؤسسان مشروعاً للبنية التحتية للذكاء الاصطناعي بـ20 مليار دولار","أسست «بروكفيلد» وشركة «قاي» المدعومة من جهاز قطر للاستثمار مشروعاً مشتركاً بقيمة 20 مليار دولار لبناء بنية تحتية للذكاء الاصطناعي، تشمل مركزاً متكاملاً للحوسبة في قطر."),
"616fbffeaa":("مايكروسوفت تكشف تفاصيل استثمارات بـ15.2 مليار دولار في الإمارات حتى 2029","أعلنت مايكروسوفت أن إنفاقها في الإمارات بين 2023 و2029 سيبلغ 15.2 مليار دولار، يشمل حصة بقيمة 1.5 مليار دولار في «جي42» وأكثر من 5.5 مليار دولار نفقات رأسمالية على البنية التحتية للذكاء الاصطناعي والسحابة اعتباراً من 2026."),
"032ccfc3a6":("هيوماين و«أمازون ويب سيرفيسز» توسّعان علاقتهما الاستراتيجية","وسّعت هيوماين وAWS في نوفمبر 2025 علاقتهما الاستراتيجية التي انطلقت في مايو من العام نفسه."),
"6470aeccbf":("هيوماين و«إيرترانك» تتفقان على مشروع مراكز بيانات بـ3 مليارات دولار","اتفقت هيوماين و«إيرترانك» المدعومة من «بلاكستون» على شراكة طويلة الأمد لتمويل وبناء وتشغيل مراكز بيانات للذكاء الاصطناعي في المملكة، تبدأ بحرم تُقدّر استثماراته بنحو 3 مليارات دولار."),
"baaf512e60":("«إم جي إكس» وشركاؤها يتفقون على شراء «ألايند داتا سنترز» بنحو 40 مليار دولار","اتفقت «إم جي إكس» و«شراكة البنية التحتية للذكاء الاصطناعي» و«جي آي بي» التابعة لبلاك روك على الاستحواذ على «ألايند داتا سنترز» بقيمة منشأة ضمنية تقارب 40 مليار دولار."),
"1a2cd2d6b0":("«سيريبراس» تعتزم نشر بنية تحتية للذكاء الاصطناعي في «ستارغيت الإمارات»","قالت «سيريبراس» الأمريكية إنها تعتزم نشر بنية تحتية للذكاء الاصطناعي في مركز «ستارغيت الإمارات» بأبوظبي."),
"4b28097c15":("هيوماين و«كوالكوم» تنشران 200 ميغاواط من أنظمة الاستدلال","تستهدف هيوماين نشر 200 ميغاواط من أنظمة «كوالكوم» AI200 وAI250 في المملكة اعتباراً من 2026، لتقديم خدمات الاستدلال محلياً وعالمياً."),
"0e631cfa98":("هيوماين و«سنتر3» توقعان اتفاقية للربط الشبكي","وقّعت هيوماين و«سنتر3» اتفاقية لتقديم خدمات اتصال متقدمة تدعم البنية التحتية للذكاء الاصطناعي لدى هيوماين."),
"118513d6b2":("واشنطن توافق على تصدير رقائق «إنفيديا» لمايكروسوفت في الإمارات","وافقت الحكومة الأمريكية على تراخيص تتيح لمايكروسوفت شحن ما يعادل 60,400 شريحة A100 من طراز GB300 إلى مراكز بياناتها في الإمارات."),
"4611b29f15":("«جي42» و«أوبن إيه آي» وشركاء عالميون يطلقون «ستارغيت الإمارات»","أعلنت «جي42» و«أوبن إيه آي» و«أوراكل» و«إنفيديا» و«سوفت بنك» و«سيسكو» إطلاق «ستارغيت الإمارات»، وهو مجمع حوسبة بقدرة 1 غيغاواط في أبوظبي، على أن تدخل مرحلته الأولى بقدرة 200 ميغاواط الخدمة في 2026."),
"33616f1bb2":("الإمارات والولايات المتحدة تعلنان حرماً للذكاء الاصطناعي بقدرة 5 غيغاواط في أبوظبي","أُعلن عن حرم الذكاء الاصطناعي الإماراتي الأمريكي بقدرة 5 غيغاواط في أبوظبي ضمن «شراكة تسريع الذكاء الاصطناعي» بين البلدين، وسيحتضن مشروع «ستارغيت الإمارات»."),
"aa05b695e1":("«أمازون ويب سيرفيسز» وهيوماين تخططان لمنطقة ذكاء اصطناعي بأكثر من 5 مليارات دولار","تعتزم AWS وهيوماين استثمار أكثر من 5 مليارات دولار في «منطقة ذكاء اصطناعي» بالمملكة، إضافة إلى استثمار AWS البالغ 5.3 مليار دولار في منطقتها السحابية السعودية المقررة في 2026."),
"d06eed371d":("«غوغل كلاود» وصندوق الاستثمارات العامة يمضيان في مركز للذكاء الاصطناعي بـ10 مليارات دولار","أعلنت «غوغل كلاود» وصندوق الاستثمارات العامة المضي في إنشاء مركز عالمي للذكاء الاصطناعي في المملكة باستثمار مشترك قدره 10 مليارات دولار، يُطلق مع هيوماين توسعةً لمنطقة الدمام السحابية."),
"eca84c69a4":("«أوراكل» تتعهد باستثمار 14 مليار دولار في السعودية خلال 10 سنوات","تعهدت «أوراكل» باستثمار 14 مليار دولار في المملكة خلال العقد المقبل، لتوفير أحدث تقنيات الحوسبة السحابية والذكاء الاصطناعي."),
"99c8dd5ec8":("«إيه إم دي» وهيوماين تطلقان تعاوناً بـ10 مليارات دولار لنشر 500 ميغاواط","اتفقت AMD وهيوماين على استثمار ما يصل إلى 10 مليارات دولار لنشر 500 ميغاواط من سعة الحوسبة للذكاء الاصطناعي خلال خمس سنوات في المملكة والولايات المتحدة."),
"7854308249":("«داتافولت» تخطط لاستثمار 20 مليار دولار في مراكز بيانات أمريكية","قال البيت الأبيض إن شركة «داتافولت» السعودية ستستثمر 20 مليار دولار في مراكز بيانات الذكاء الاصطناعي والبنية التحتية للطاقة في الولايات المتحدة."),
"60eacc85d6":("«سدايا» توقع مذكرات تفاهم مع «إيه إم دي» وشركات تقنية أمريكية","وقّعت الهيئة السعودية للبيانات والذكاء الاصطناعي «سدايا» مذكرات تفاهم مع شركات تقنية أمريكية على هامش منتدى الاستثمار السعودي الأمريكي، تشمل مراكز بيانات للذكاء الاصطناعي ومركز تميز للحوسبة السحابية والبنية التحتية للبيانات."),
"ca5475a0c2":("هيوماين تبني «مصانع ذكاء اصطناعي» بقدرة تصل إلى 500 ميغاواط بتقنيات «إنفيديا»","تخطط هيوماين لبناء مصانع ذكاء اصطناعي بقدرة تصل إلى 500 ميغاواط تعمل بمئات الآلاف من معالجات «إنفيديا» خلال خمس سنوات، تبدأ بحاسوب فائق يضم 18 ألف شريحة GB300."),
"298ea1898d":("«سدايا» و«إنفيديا» تنشران حتى 5 آلاف معالج لمصنع ذكاء اصطناعي سيادي","تنشر «سدايا» و«إنفيديا» ما يصل إلى 5 آلاف معالج من طراز «بلاكويل» لإنشاء مصنع ذكاء اصطناعي سيادي، مع تدريب مهندسين وعلماء من الجهات الحكومية والجامعات."),
"66898ea779":("«أرامكو الرقمية» و«إنفيديا» تتعاونان في البنية التحتية للذكاء الاصطناعي","اتفقت «أرامكو الرقمية» و«إنفيديا» على تطوير بنية تحتية للذكاء الاصطناعي وإنشاء مركز تميز هندسي في المملكة."),
"f265328c7a":("ولي العهد يطلق «هيوماين» شركةً للذكاء الاصطناعي مملوكة لصندوق الاستثمارات العامة","أطلق صاحب السمو الملكي الأمير محمد بن سلمان، ولي العهد، شركة «هيوماين» المملوكة لصندوق الاستثمارات العامة، لتعمل عبر سلسلة القيمة للذكاء الاصطناعي من مراكز البيانات والسحابة إلى النماذج المتقدمة ونموذج لغوي عربي متعدد الوسائط."),
"b12a81df16":("«غروك» تحصل على التزام سعودي بـ1.5 مليار دولار لتوسعة مركز الدمام","حصلت «غروك» الأمريكية لرقائق الذكاء الاصطناعي على التزام بقيمة 1.5 مليار دولار من المملكة خلال مؤتمر «ليب 2025»، لتوسعة بنيتها للاستدلال بما في ذلك مركز بياناتها في الدمام."),
"5111fd3f73":("«إم جي إكس» تنضم إلى «ستارغيت» الأمريكي بمساهمة تُقدّر بنحو 7 مليارات دولار","انضمت «إم جي إكس»، ومقرها أبوظبي، إلى مشروع «ستارغيت» في الولايات المتحدة، وتشير تقارير إلى أنها تعتزم المساهمة بنحو 7 مليارات دولار."),
}
UC={
"abu-dhabi-tamm-autogov-runs-recurring-services-automatically":("«أوتوغوف» في تطبيق «تم» ينجز الخدمات المتكررة تلقائياً","أضافت النسخة الرابعة من «تم» خاصية «أوتوغوف» التي تتولى تلقائياً المعاملات المتكررة مثل تجديد الرخص وسداد الفواتير وحجز المواعيد الصحية، وفق تفضيلات يحددها المستخدم.","1) حصر المعاملات المتكررة الأعلى تكراراً. 2) إتاحة الاشتراك الاختياري مع ضوابط كسقف المبلغ والتنبيهات. 3) تشغيل وكيل يرصد مواعيد الاستحقاق ويعبئ الطلبات ويرسلها ويُخطر المستخدم. 4) تسجيل كل إجراء للتدقيق مع إمكانية التراجع بنقرة."),
"tamm-ai-assistant-completes-services-on-the-user-s-behalf":("المساعد الذكي في «تم» ينجز الخدمات نيابة عن المتعامل","يقدم المساعد الذكي في «تم» دعماً استباقياً عبر أكثر من 1,100 خدمة حكومية وخاصة من أكثر من 90 جهة، ويستطيع إتمام كثير منها نيابة عن المتعامل.","1) تحويل اشتراطات الخدمات إلى قاعدة معرفة منظمة. 2) منح المساعد صلاحيات لواجهات التحقق من الأهلية وتقديم الطلبات. 3) اشتراط تأكيد صريح من المستخدم قبل التقديم. 4) التحويل إلى موظف عند الحالات الاستثنائية."),
"uae-federal-tax-audit-ai-agent":("وكيل ذكاء اصطناعي اتحادي للتدقيق الضريبي في الإمارات","أطلقت الإمارات في مايو 2026 أولى دفعات الوكلاء الذكيين الحكوميين، ومنها وكيل للتدقيق الضريبي يعزز التحقق من البيانات ومراجعتها لتسريع الامتثال والتدقيق.","1) تغذية الوكيل بالإقرارات والبيانات المرجعية. 2) رصد التباينات مقارنة بالقواعد والفترات السابقة. 3) إعداد ملف أدلة لكل ملاحظة. 4) اعتماد المدققين للنتائج وإعادة تغذية النموذج بها."),
"uae-customer-happiness-ai-agent-for-service-staff":("وكيل «إسعاد المتعاملين» يدعم موظفي الخدمة الحكومية","يزوّد وكيل إسعاد المتعاملين الموظفين بالمعلومات الأساسية بسرعة لتحسين الردود، ضمن خطة لتقديم نصف الخدمات الحكومية عبر الذكاء الاصطناعي الوكيلي خلال عامين.","1) بناء فهرس بحث للسياسات والأسئلة الشائعة بالعربية والإنجليزية. 2) عرض إجابات مقترحة مع مصادرها في شاشة الموظف. 3) قياس زمن المعالجة والدقة. 4) التوسع إلى الخدمة الذاتية بعد ثبوت الدقة."),
"uae-government-procurement-and-it-support-agents":("وكلاء ذكيون للمشتريات والدعم التقني في الحكومة الاتحادية","شملت الدفعة الأولى في مايو 2026 وكيلاً للمشتريات وآخر للدعم التقني يدير خدمات تقنية المعلومات ويساند الفرق الفنية.","1) البدء بفرز التذاكر وتصنيفها وتوجيهها واقتراح الحلول. 2) تكليف وكيل المشتريات بصياغة طلبات التسعير ومقارنة العروض. 3) إبقاء قرارات الترسية والصرف بيد الموظفين."),
"tawakkalna-scales-to-1-000-integrated-government-services":("«توكلنا» يتجاوز 1,000 خدمة حكومية مدمجة","عقدت «سدايا» أكثر من 60 لقاءً تعريفياً مع أكثر من 100 جهة حكومية لدمج خدماتها في تطبيق «توكلنا» الذي بات يضم أكثر من 1,000 خدمة رقمية.","1) نشر حزمة تكامل موحدة من واجهات برمجية ومكونات واجهة. 2) تنظيم ورش تأهيل لكل جهة. 3) قياس زمن إطلاق كل خدمة. 4) توحيد الهوية والمدفوعات عبر الخدمات."),
"emirates-nbd-enterprise-conversational-agent-platform":("الإمارات دبي الوطني تعتمد منصة مؤسسية للوكلاء المحادثين","تدير الإمارات دبي الوطني أكثر من 100 حالة استخدام للذكاء الاصطناعي، وتستند منصتها للوكلاء المحادثين إلى معرفة معتمدة مع ضوابط واضحة وتحويل سلس إلى الموظفين.","1) إعداد قاعدة معرفة معتمدة. 2) ربط كل إجابة بها ورفض الأسئلة خارج النطاق. 3) وضع ضوابط للبيانات الشخصية والنصائح المالية. 4) إتاحة التحويل إلى موظف بنقرة واحدة."),
"fab-runs-30-agentic-ai-use-cases-in-production":("بنك أبوظبي الأول يشغّل أكثر من 30 حالة استخدام للذكاء الاصطناعي الوكيلي","أعلن بنك أبوظبي الأول في فبراير 2026 تقدّم أكثر من 30 حالة استخدام للذكاء الاصطناعي الوكيلي في التجارة والمدفوعات وعمليات العملاء والامتثال، على منصة بيانات تدمج أكثر من 90% من بياناته المنظمة.","1) تأسيس مركز موحد للذكاء الاصطناعي بحوكمة ومكونات قابلة لإعادة الاستخدام. 2) توحيد البيانات أولاً. 3) اختيار عمليات كثيفة كوثائق التجارة واستثناءات المدفوعات. 4) قياس الإنتاجية قبل التوسع."),
"al-rajhi-arabic-assistant-and-ai-fraud-detection":("مصرف الراجحي يعتمد منصة «فوكال» من «موزن» لمكافحة الاحتيال","تعاون مصرف الراجحي مع «موزن» في أكتوبر 2025 لنشر منصة «فوكال» للذكاء الاصطناعي في الوقاية من الجرائم المالية، بهدف رصد الاحتيال لحظياً وتعزيز إدارة المخاطر.","1) تمرير عمليات البطاقات والتحويلات إلى محرك لتقييم المخاطر. 2) التقييم اللحظي وتعليق العمليات عالية الخطورة. 3) طلب تأكيد العميل. 4) إحالة الحالات إلى المحققين مع تفسير قرار النموذج."),
"adnoc-energyai-agents-across-upstream":("«أدنوك» تنشر وكلاء «إنرجي إيه آي» في عمليات الاستكشاف والإنتاج","وقّعت «إيه آي كيو» عقداً بقيمة 340 مليون دولار لثلاث سنوات لنشر حل «إنرجي إيه آي» الوكيلي في عمليات «أدنوك» للاستكشاف والإنتاج، من تحليل البيانات الزلزالية إلى النمذجة الجيولوجية ومراقبة العمليات.","1) اختيار عملية محددة مثل تفسير البيانات الزلزالية. 2) إثبات الجدوى بتجربة أولية مع الخبراء. 3) بناء وكلاء متخصصين على البيانات الخاصة. 4) التوسع حقلاً تلو آخر."),
"aramco-metabrain-industrial-llm":("أرامكو تطوّر «ميتابرين» أول نموذج لغوي صناعي كبير","درّبت أرامكو نموذجها الصناعي «ميتابرين» على بيانات تراكمت لعقود، ليضع خبرة الشركة في متناول المشغلين والفنيين والمهندسين، مدعوماً بعنقود حوسبة من «إنفيديا».","1) جمع الأدلة والتقارير وسجلات الحوادث. 2) تدريب نموذج أو ربطه بالبحث في هذه الوثائق. 3) إتاحته للفرق الميدانية مع الإحالة إلى المصادر. 4) إطلاق برنامج موازٍ لأمن الذكاء الاصطناعي."),
"autonomous-control-ai-agents-at-fadhili-gas-plant":("وكلاء تحكم ذاتي بالذكاء الاصطناعي في معمل غاز الفاضلي","نشرت «يوكوغاوا» وكلاء ذكاء اصطناعي قائمين على التعلم المعزز يتحكمون ذاتياً في وحدة إزالة الغازات الحمضية بمعمل الفاضلي التابع لأرامكو، وأظهرت النتائج الأولية خفض استهلاك الأمين والبخار 10-15% والكهرباء نحو 5%.","1) اختيار وحدة مزودة بأجهزة قياس كافية. 2) تدريب التحكم على البيانات التاريخية ونموذج محاكاة. 3) التشغيل استشارياً ثم بحلقة مغلقة ضمن حدود آمنة. 4) متابعة الطاقة والمواد الكيميائية والاستقرار."),
"emirates-post-ai-parcel-segregation":("بريد الإمارات يفرز الطرود بالذكاء الاصطناعي","طبّقت مجموعة بريد الإمارات نظاماً للتعرف على الصور يصنّف الطرود حسب الحجم والوزن والوجهة ويوجهها آلياً إلى خطوط الفرز.","1) تركيب كاميرات وموازين على خط الإدخال. 2) تدريب نموذج تصنيف على صور طرود موسومة. 3) ربط بوابات الفرز بنتائج النموذج. 4) تحويل الحالات منخفضة الثقة إلى المراجعة اليدوية."),
"aramex-ai-first-data-foundation":("«أرامكس» تطلق منصة بيانات قائمة على الذكاء الاصطناعي","أطلقت «أرامكس» منصة بيانات عالمية على «غوغل كلاود» لتتبع الشحنات لحظياً وتحسين المسارات ديناميكياً والتنبيه المسبق بالتأخير عبر أكثر من 70 دولة.","1) توحيد أحداث الشحن في مستودع بيانات واحد. 2) تدريب نماذج للتنبؤ بالتأخير. 3) إرسال إشعارات استباقية للعملاء. 4) إعادة تغذية أنظمة التوزيع بالمسارات المحسّنة."),
"dp-world-cargoes-flow-visibility-at-jebel-ali":("منصة «كارغوز فلو» من موانئ دبي العالمية لتتبع الشحنات","أتاحت موانئ دبي العالمية منصة «كارغوز فلو» لتتبع الشحنات البحرية والجوية والبرية من المنشأ إلى الوجهة.","1) ربط بيانات شركات الشحن والموانئ عبر واجهات برمجية. 2) بناء عرض موحد ولحظي للشحنات. 3) توظيف الذكاء الاصطناعي للتنبؤ بمواعيد الوصول ورصد الاستثناءات. 4) أتمتة تحديثات العملاء."),
"ai-agent-pre-checks-zatca-invoices-before-submission":("وكيل ذكي يفحص فواتير «فاتورة» قبل إرسالها إلى «زاتكا»","أضافت مجموعة تجزئة سعودية تصدر أكثر من 50 ألف فاتورة شهرياً طبقة امتثال بالذكاء الاصطناعي فوق تكاملها مع المرحلة الثانية، فانخفض معدل الرفض من 3-5% إلى 0.15% (دراسة حالة من المورّد).","1) توحيد الفواتير من جميع المصادر. 2) التحقق منها مقابل قواعد «زاتكا» قبل الإرسال. 3) التعلم من حالات الرفض السابقة. 4) تصحيح المشكلات الآمنة آلياً وإحالة البقية إلى المالية."),
"zatca-phase-2-integration-on-odoo":("تكامل المرحلة الثانية من الفوترة الإلكترونية على «أودو»","أتمتت شركة تجزئة وتصنيع سعودية إصدار شهادات التشفير والتوقيع والاعتماد اللحظي للفواتير ورموز QR عبر «أودو» (دراسة حالة من المورّد).","1) التسجيل في بيئة الاختبار للحصول على الشهادات. 2) توليد فواتير XML بصيغة UBL 2.1 مع التجزئة والتوقيع. 3) إدارة طابور الإرسال مع إعادة المحاولة. 4) مراقبة حالات الرفض عبر لوحة متابعة."),
"zatca-e-invoicing-middleware-for-dynamics-365-business-central":("وسيط معتمد من «زاتكا» لنظام «دايناميكس 365»","اعتمدت «دومينيون غلوبال» حلاً وسيطاً معتمداً من «زاتكا» مرتبطاً بنظام Business Central لأتمتة التحقق والاعتماد والإبلاغ (دراسة حالة من جهة التنفيذ).","1) اختيار حل وسيط معتمد لنظامك. 2) مطابقة حقول الفاتورة. 3) الاختبار ثم التشغيل وفق موجة الربط. 4) أرشفة الفواتير ومطابقتها آلياً."),
"zatca-integration-for-oracle-fusion":("ربط «أوراكل فيوجن» بمنصة «فاتورة»","ربطت مجموعة خليجية للهندسة والتجارة نظام «أوراكل فيوجن» بمنصة «فاتورة» مع التحقق والمراقبة المركزية واختبارات القبول ودعم مُدار لمدة 12 شهراً (دراسة حالة من جهة التنفيذ).","1) تقييم إعدادات النظام الحالية. 2) بناء موصلات للإصدار والإرسال واسترجاع الحالة. 3) إضافة مراقبة مركزية. 4) التخطيط للانتقال والدعم بعد التشغيل."),
"aldar-voice-enabled-agentic-payment":("«الدار» و«فيزا» تنفذان أول دفعة صوتية عبر وكيل ذكي في المنطقة","أتمّت «فيزا» و«الدار» أول عملية دفع وكيلية صوتية متكاملة في المنطقة، تتيح للسكان سداد رسوم الخدمات عبر وكيل ذكاء اصطناعي.","1) إتاحة واجهة دفع ببطاقات مرمّزة. 2) إضافة وكيل صوتي يتحقق من الهوية ويؤكد المبلغ. 3) اشتراط موافقة صريحة صوتية أو حيوية. 4) إرسال الإيصال وحفظ نص المحادثة."),
"dubai-land-department-ai-initial-registration":("دائرة الأراضي والأملاك في دبي تطلق منصة «التسجيل المبدئي» بالذكاء الاصطناعي","أطلقت الدائرة منصة للتسجيل المبدئي تستخرج البيانات من المستندات آلياً وتعتمد معاملات المطورين المستوفية للشروط.","1) تحديد قواعد الأهلية. 2) استخراج الحقول بالذكاء الاصطناعي من المستندات. 3) اعتماد الحالات المكتملة آلياً وإحالة البقية للمراجعة. 4) تدقيق عينات من الاعتمادات الآلية."),
"dubai-land-department-and-google-cloud-smart-solutions":("دائرة الأراضي والأملاك و«غوغل كلاود» تطوران حلولاً ذكية للسوق العقاري","تعاونت الدائرة مع «غوغل كلاود» على حلول ذكية ترفع كفاءة السوق وتحسن تجربة المستثمرين.","1) مركزة بيانات العقارات سحابياً. 2) إضافة بحث وتحليلات ذكية للمستثمرين. 3) نشر مؤشرات السوق. 4) التطوير المستمر وفق ملاحظات المستخدمين."),
"seha-virtual-hospital-ai-heart-diagnosis":("مستشفى صحة الافتراضي يثبت تفوق الذكاء الاصطناعي في تشخيص القلب","أعلنت وزارة الصحة أن مستشفى صحة الافتراضي أثبت كفاءة الذكاء الاصطناعي في تشخيص أمراض القلب.","1) اختيار مهمة تشخيصية عالية الحجم. 2) التحقق من النموذج مقارنة بقراءات الاستشاريين. 3) استخدامه أداةً مساندة للقرار. 4) مراقبة الدقة باستمرار."),
"ehs-amal-ai-physician-assistant":("مؤسسة الإمارات للخدمات الصحية تطلق «أمل» مساعداً ذكياً للأطباء","أطلقت المؤسسة «أمل»، مساعداً متعدد الوكلاء مستضافاً داخل الدولة، يجمع التاريخ المرضي قبل الاستشارة ويعد ملخصاً للطبيب، بدءاً بالاستشارات عن بُعد.","1) تكليف الوكيل بأخذ التاريخ المرضي قبل الموعد. 2) إعداد ملخص منظم للطبيب. 3) الاستضافة محلياً لضمان سيادة البيانات. 4) البدء بالاستشارات منخفضة الخطورة."),
"m42-predictive-health-in-abu-dhabi":("«إم 42» توظف الذكاء الاصطناعي للتنبؤ بالأمراض في أبوظبي","قال الرئيس التنفيذي لـ«إم 42» إن المنظومة الصحية في أبوظبي باتت تتنبأ بالأمراض قبل ظهورها، عبر أدوات سريرية ذكية تحت إشراف الأطباء.","1) دمج السجلات الصحية والبيانات الجينومية بموافقة المرضى. 2) بناء نماذج لتقدير مخاطر الأمراض المزمنة. 3) التواصل الاستباقي مع الفئات الأعلى خطراً. 4) قياس النتائج الصحية."),
"emirates-group-and-openai-collaboration":("مجموعة الإمارات تتعاون مع «أوبن إيه آي» لتسريع تبني الذكاء الاصطناعي","أعلنت مجموعة الإمارات تعاوناً مع «أوبن إيه آي» لتسريع تبني الذكاء الاصطناعي والابتكار على مستوى المؤسسة.","1) إتاحة مساعد مؤسسي للموظفين. 2) تحديد أهم مسارات العمل في العمليات وخدمة العملاء. 3) بناء وكلاء مخصصين بضوابط واضحة. 4) تأهيل سفراء للذكاء الاصطناعي في كل إدارة."),
"airline-agentic-ai-cuts-live-contacts-by-45":("ناقلة جوية في المنطقة تخفض الاتصالات المباشرة 45% بالذكاء الاصطناعي الوكيلي","استخدمت ناقلة جوية رائدة في الشرق الأوسط ذكاءً اصطناعياً وكيلياً متعدد اللغات لإدارة الاضطرابات والخدمة الذاتية، فخفضت الاتصالات المباشرة بما يصل إلى 45% (دراسة حالة من المورّد).","1) أتمتة إعادة الحجز والاسترداد بالكامل. 2) إرسال رسائل استباقية عند الاضطرابات. 3) دعم العربية والإنجليزية صوتاً وكتابة. 4) متابعة نسب الحل الذاتي في أوقات الذروة."),
"e-rolls-arabic-copilot-to-50k-staff":("«إي آند الإمارات» تنشر «مايكروسوفت 365 كوبايلوت» على نطاق واسع","أعلنت «إي آند الإمارات» في مارس 2025 نشر «مايكروسوفت 365 كوبايلوت» على نطاق واسع لتطوير بيئة العمل بالذكاء الاصطناعي.","1) البدء بتجربة مع المستخدمين الأكثر نشاطاً. 2) ضبط صلاحيات الوصول قبل التعميم. 3) توفير مكتبة أوامر باللغة العربية. 4) قياس معدلات الاستخدام لكل فريق."),
"arabic-voice-agents-live-at-e":("«عربي إيه آي» و«هاي بريز» تتعاونان في الوكلاء الصوتيين العرب للمؤسسات","أعلنت «عربي إيه آي» و«هاي بريز» في أبريل 2026 شراكة لتشغيل وكلاء صوتيين بالعربية على نطاق مؤسسي، تجمع نماذج تراعي اللهجات مع بنية اتصال منخفضة التأخير.","1) تحديد أبرز أسباب الاتصال. 2) نشر تعرّف كلام وتحويل نص إلى كلام يراعيان اللهجات. 3) الربط بأنظمة الفوترة وإدارة العملاء. 4) التحويل إلى الموظف مع السياق الكامل."),
"stc-bahrain-gennext-contact-centre":("«stc البحرين» تطلق مركز اتصال متكاملاً من الجيل الجديد","كشفت «stc البحرين» عن مركز اتصال متكامل يضم وكلاء صوتيين ونصيين يتحدثون اللهجات العربية، بهدف حل معظم الاستفسارات الروتينية.","1) توحيد قنوات الصوت والمحادثة والتواصل الاجتماعي. 2) إضافة روبوتات باللهجات للاستفسارات الروتينية. 3) تزويد الموظفين بملخصات ذكية. 4) نشر معدلات الحل."),
"dewa-rammas-virtual-employee":("«رمّاس» موظف «ديوا» الافتراضي يتعامل مع 1.6 مليون استفسار","تعامل «رمّاس»، الموظف الافتراضي لهيئة كهرباء ومياه دبي، مع أكثر من 1.6 مليون استفسار خلال 2025.","1) البدء باستفسارات الفواتير والتوصيل والانقطاعات. 2) ربط الإجابات ببيانات الحساب. 3) دعم العربية والإنجليزية. 4) نشر الأحجام ومؤشرات الرضا."),
"dewa-services-in-the-chatgpt-apps-directory":("«ديوا» تتيح خدماتها عبر دليل تطبيقات «تشات جي بي تي»","أتاحت هيئة كهرباء ومياه دبي خدماتها عبر دليل تطبيقات «تشات جي بي تي».","1) إتاحة واجهات خدمات آمنة. 2) بناء تطبيق أو موصل لمنصة المساعد. 3) التحقق من المستخدمين عبر OAuth. 4) البدء بالإجراءات الآمنة القابلة للتراجع."),
"dewa-deploys-agentic-ai-across-digital-platforms":("«ديوا» تعمّم الذكاء الاصطناعي الوكيلي على منصاتها الرقمية","نشرت هيئة كهرباء ومياه دبي الذكاء الاصطناعي الوكيلي عبر منصاتها الرقمية.","1) حصر رحلات المتعاملين. 2) إضافة وكلاء ينجزون الطلبات متعددة الخطوات. 3) إبقاء الموافقة البشرية للإجراءات الحساسة. 4) المراقبة والتحسين المستمر."),
"dubai-rta-ai-strategy-2030-with-81-projects":("هيئة الطرق والمواصلات في دبي تطلق استراتيجية الذكاء الاصطناعي 2030 بـ81 مشروعاً","أطلقت الهيئة استراتيجية للذكاء الاصطناعي حتى 2030 تضم 81 مشروعاً ومبادرة، من بينها توظيف الذكاء الاصطناعي التوليدي في المساعد الافتراضي «محبوب».","1) بناء محفظة حالات استخدام مرتبة حسب الأثر. 2) ترقية المساعدات الحالية بالذكاء التوليدي. 3) تحديد مؤشرات أداء لكل مشروع. 4) المراجعة السنوية."),
"dubai-agentic-ai-for-government-services-accelerator":("مسرّعة دبي للذكاء الاصطناعي الوكيلي في الخدمات الحكومية","أطلقت دبي مسرّعة للذكاء الاصطناعي الوكيلي في الخدمات الحكومية بمشاركة 33 جهة وأكثر من 300 حالة استخدام.","1) جمع حالات الاستخدام من الجهات. 2) ربط الجهات بالموردين في دورات قصيرة. 3) اعتماد إرشادات امتثال موحدة. 4) تعميم التجارب الناجحة."),
"abu-dhabi-ainative-training-for-all-government-staff":("أبوظبي تطلق برنامج «AiNative» لتدريب موظفي الحكومة والجمهور","أطلقت أبوظبي مبادرة «AiNative» لتدريب جميع موظفي الحكومة وأفراد المجتمع على الذكاء الاصطناعي.","1) تحديد مستويات المهارة حسب الدور. 2) تقديم وحدات تطبيقية قصيرة. 3) منح شهادات للموظفين. 4) ربط التدريب بحالات استخدام فعلية."),
"uae-trains-80-000-federal-staff-to-work-with-ai-agents":("الإمارات تدرّب 80 ألف موظف اتحادي على العمل مع الوكلاء الذكيين","كشف مجلس الوزراء عن خطة لتدريب 80 ألف موظف حكومي، من الوزراء إلى الموظفين الجدد، على استخدام الوكلاء الذكيين عبر منصة تعلم قائمة على الذكاء الاصطناعي الوكيلي.","1) تصنيف الموظفين حسب الدور. 2) إعداد وحدات قصيرة لكل فئة. 3) توظيف معلم ذكي لتخصيص مسارات التعلم. 4) ربط الإتمام بمشاريع فعلية."),
"napster-and-humain-deploy-arabic-native-voice-and-video-ai-agents":("نابستر وهيوماين تنشران وكلاء صوتيين ومرئيين ناطقين بالعربية","تجمع «نابستر» و«هيوماين» نموذج «علّام» وتقنيات التعرف على الكلام العربي وتحويل النص إلى كلام بلهجات متعددة مع بنية نابستر للوكلاء متعددي الوسائط.","1) اختيار حالة استخدام أمامية كخدمة المتعاملين. 2) استخدام نموذج عربي مع تقنيات الكلام العربية. 3) حفظ سياق المحادثات السابقة بموافقة المستخدم. 4) التحويل إلى الموظف مع نص المحادثة."),
"sirdab-uses-ai-to-match-shippers-with-warehouse-and-carrier-capacity":("«سرداب» توظف الذكاء الاصطناعي لمطابقة الشاحنين مع المستودعات والناقلين","تطوّر منصة «سرداب» السعودية أدوات ذكاء اصطناعي تطابق الشركات مع السعة المناسبة وتؤتمت التنسيق بين الشاحنين والمستودعات والناقلين.","1) رقمنة السعة المتاحة من مساحات وشاحنات. 2) جمع متطلبات الشحن بصيغة منظمة. 3) ترتيب الخيارات حسب السعر والموقع ومستوى الخدمة. 4) أتمتة الحجز وتحديثات الحالة."),
"synapse-analytics-brings-agentic-ai-to-banks-and-fintechs":("«سينابس أناليتكس» تقدم الذكاء الاصطناعي الوكيلي للبنوك وشركات التقنية المالية","تخدم «سينابس أناليتكس»، ومقرها أبوظبي، البنوك وشركات التمويل والتقنية المالية والاتصالات بمنصة للذكاء الاصطناعي الوكيلي.","1) البدء بقرارات الائتمان أو التحصيل. 2) ربط بيانات الائتمان والمعاملات والبيانات البديلة. 3) تمكين الوكلاء من إعداد القرارات ضمن حدود السياسات. 4) إبقاء الاستثناءات والتدقيق بيد الموظفين."),
}
