TOOLNAME_AR={"jais-2":"جيس 2","falcon-h1-arabic":"فالكون H1 العربي","fanar":"فنار","allam":"علّام","silma":"سلمى","noor":"نور","mawdoo3-ai-apis":"واجهات «موضوع» للذكاء الاصطناعي","baseer":"بصير","baseer-nakba":"بصير - نكبة","qari-ocr":"قارئ OCR","munsit-stt":"منصت - تحويل الكلام إلى نص","munsit-faseeh-tts":"منصت فصيح","lahajati":"لهجاتي","arabic-ai-suite":"منصة عربي إيه آي","maqsam-ai-agent":"وكيل مقسم الذكي","mozn-focal":"موزن فوكال","lucidya":"لوسيديا","wittify":"ويتيفاي"}
def merge(root="."):
    D=json.load(open(f"{root}/data/deals.json"))
    for d in D:
        if d["id"] in DEALS: d["title_ar"],d["summary_ar"]=DEALS[d["id"]]
    json.dump(D,open(f"{root}/data/deals.json","w"),indent=1,ensure_ascii=False)
    U=json.load(open(f"{root}/data/use_cases.json"))
    for u in U:
        if u["slug"] in UC: u["title_ar"],u["summary_ar"],u["how_to_ar"]=UC[u["slug"]]
    json.dump(U,open(f"{root}/data/use_cases.json","w"),indent=1,ensure_ascii=False)
    T=json.load(open(f"{root}/data/tools.json"))
    for t in T:
        if t["slug"] in TOOLS: t["description_ar"],t["arabic_support_ar"]=TOOLS[t["slug"]]
        t["name_ar"]=TOOLNAME_AR.get(t["slug"],t["name"])
    json.dump(T,open(f"{root}/data/tools.json","w"),indent=1,ensure_ascii=False)
    miss=[d["id"] for d in D if d.get("status")!="unreviewed" and "title_ar" not in d]+[u["slug"] for u in U if "title_ar" not in u]+[t["slug"] for t in T if "description_ar" not in t]
    print("arabic merged; missing:",miss)
if __name__=="__main__": merge()
